import json

_SPEC = json.loads("{\"sql\":[\"-- Ledger-owned data only. Existing identity and platform billing data stay separate.\\n-- All timestamps are UTC ISO 8601 text; occurred_on is a user-supplied business date.\\nCREATE TABLE ledger_projects (\\n  id TEXT PRIMARY KEY,\\n  owner_id TEXT NOT NULL,\\n  github_repo_id INTEGER NOT NULL CHECK (github_repo_id > 0),\\n  github_full_name TEXT NOT NULL,\\n  description TEXT NOT NULL DEFAULT '' CHECK (length(description) <= 2000),\\n  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'archived')),\\n  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),\\n  created_at TEXT NOT NULL,\\n  updated_at TEXT NOT NULL,\\n  UNIQUE (owner_id, github_repo_id),\\n  UNIQUE (owner_id, id)\\n);\",\"CREATE INDEX ledger_projects_owner_status ON ledger_projects(owner_id, status);\",\"CREATE TABLE expense_categories (\\n  id TEXT PRIMARY KEY,\\n  owner_id TEXT NOT NULL,\\n  name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 80),\\n  color TEXT CHECK (color IS NULL OR length(color) <= 32),\\n  archived_at TEXT,\\n  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),\\n  created_at TEXT NOT NULL,\\n  updated_at TEXT NOT NULL,\\n  UNIQUE (owner_id, id)\\n);\",\"CREATE UNIQUE INDEX expense_categories_active_name\\n  ON expense_categories(owner_id, lower(name)) WHERE archived_at IS NULL;\",\"CREATE TABLE expenses (\\n  id TEXT PRIMARY KEY,\\n  owner_id TEXT NOT NULL,\\n  target_kind TEXT NOT NULL CHECK (target_kind IN ('project', 'shared')),\\n  project_id TEXT,\\n  category_id TEXT NOT NULL,\\n  occurred_on TEXT NOT NULL CHECK (\\n    length(occurred_on) = 10 AND occurred_on GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'\\n  ),\\n  amount_minor INTEGER NOT NULL CHECK (amount_minor BETWEEN 0 AND 9007199254740991),\\n  currency TEXT NOT NULL CHECK (length(currency) = 3 AND currency GLOB '[A-Z][A-Z][A-Z]'),\\n  purpose TEXT NOT NULL CHECK (length(purpose) BETWEEN 1 AND 500),\\n  note TEXT CHECK (note IS NULL OR length(note) <= 4000),\\n  quantity_decimal TEXT CHECK (quantity_decimal IS NULL OR length(quantity_decimal) BETWEEN 1 AND 40),\\n  unit TEXT CHECK (unit IS NULL OR length(unit) <= 40),\\n  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),\\n  created_at TEXT NOT NULL,\\n  updated_at TEXT NOT NULL,\\n  deleted_at TEXT,\\n  CHECK ((target_kind = 'shared' AND project_id IS NULL) OR\\n         (target_kind = 'project' AND project_id IS NOT NULL)),\\n  FOREIGN KEY (owner_id, project_id) REFERENCES ledger_projects(owner_id, id) ON DELETE RESTRICT,\\n  FOREIGN KEY (owner_id, category_id) REFERENCES expense_categories(owner_id, id) ON DELETE RESTRICT,\\n  UNIQUE (owner_id, id)\\n);\",\"CREATE INDEX expenses_owner_target_date\\n  ON expenses(owner_id, target_kind, project_id, occurred_on, category_id, id)\\n  WHERE deleted_at IS NULL;\",\"CREATE INDEX expenses_owner_category_date\\n  ON expenses(owner_id, category_id, occurred_on, id)\\n  WHERE deleted_at IS NULL;\",\"CREATE TABLE expense_events (\\n  id TEXT PRIMARY KEY,\\n  expense_id TEXT NOT NULL,\\n  owner_id TEXT NOT NULL,\\n  actor_kind TEXT NOT NULL CHECK (actor_kind IN ('session', 'api_key')),\\n  actor_id TEXT NOT NULL,\\n  action TEXT NOT NULL CHECK (action IN ('create', 'update', 'delete', 'restore')),\\n  before_json TEXT,\\n  after_json TEXT,\\n  created_at TEXT NOT NULL,\\n  FOREIGN KEY (owner_id, expense_id) REFERENCES expenses(owner_id, id) ON DELETE RESTRICT\\n);\",\"CREATE INDEX expense_events_owner_expense ON expense_events(owner_id, expense_id, created_at, id);\",\"-- An owner and key identify one creation request. The stored response allows exact replay.\\nCREATE TABLE expense_create_idempotency (\\n  owner_id TEXT NOT NULL,\\n  idempotency_key TEXT NOT NULL,\\n  request_sha256 TEXT NOT NULL,\\n  expense_id TEXT NOT NULL,\\n  response_json TEXT NOT NULL,\\n  created_at TEXT NOT NULL,\\n  PRIMARY KEY (owner_id, idempotency_key),\\n  FOREIGN KEY (owner_id, expense_id) REFERENCES expenses(owner_id, id) ON DELETE RESTRICT\\n);\",\"-- Runtime foundation for S03-S05 on a fresh D1 database.\\n-- Account and platform billing facts stay separate from ledger expenses.\\nCREATE TABLE IF NOT EXISTS app_state (\\n  name TEXT PRIMARY KEY, payload TEXT NOT NULL, updated_at INTEGER NOT NULL\\n);\",\"INSERT OR IGNORE INTO app_state(name,payload,updated_at) VALUES\\n  ('users','{}',0),('sessions','{}',0),('billingEvents','{}',0),\\n  ('billingPendingUpdates','[]',0);\",\"CREATE TABLE IF NOT EXISTS d1_command_guard (ok INTEGER NOT NULL CHECK(ok=1));\",\"CREATE TABLE IF NOT EXISTS api_keys (\\n  id TEXT PRIMARY KEY, user_id TEXT NOT NULL, name TEXT NOT NULL,\\n  key_prefix TEXT NOT NULL, key_hash TEXT NOT NULL UNIQUE,\\n  scopes TEXT NOT NULL DEFAULT '[]', expires_at INTEGER,\\n  restrictions TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL,\\n  last_used_at INTEGER, revoked_at INTEGER\\n);\",\"CREATE INDEX IF NOT EXISTS idx_api_keys_user ON api_keys(user_id,revoked_at);\",\"CREATE TABLE IF NOT EXISTS account_entitlement_authority (\\n  owner_id TEXT PRIMARY KEY, revision INTEGER NOT NULL CHECK(revision>=1),\\n  plan TEXT NOT NULL, period TEXT NOT NULL,\\n  period_start INTEGER NOT NULL CHECK(period_start>=0),\\n  valid_until INTEGER NOT NULL, dirty INTEGER NOT NULL CHECK(dirty IN (0,1))\\n);\",\"CREATE TABLE IF NOT EXISTS billing_webhook_receipts (\\n  event_id TEXT PRIMARY KEY, raw_sha256 TEXT NOT NULL, update_json TEXT NOT NULL,\\n  received_at INTEGER NOT NULL,\\n  state TEXT NOT NULL CHECK(state IN ('pending','applied'))\\n);\",\"CREATE TABLE IF NOT EXISTS billing_public_catalog (\\n  id INTEGER PRIMARY KEY CHECK(id=1), payload_json TEXT NOT NULL,\\n  expires_at INTEGER NOT NULL, source_revision INTEGER NOT NULL,\\n  updated_at INTEGER NOT NULL\\n);\",\"-- Optional suggestion calls and outcomes. These tables never post an expense.\\nCREATE TABLE expense_suggestion_budget (\\n  owner_id TEXT NOT NULL,\\n  day TEXT NOT NULL,\\n  attempts INTEGER NOT NULL CHECK (attempts BETWEEN 0 AND 20),\\n  PRIMARY KEY (owner_id, day)\\n);\",\"CREATE TABLE expense_suggestion_events (\\n  id TEXT PRIMARY KEY,\\n  owner_id TEXT NOT NULL,\\n  created_at TEXT NOT NULL,\\n  question_version TEXT NOT NULL,\\n  draft_target_kind TEXT NOT NULL,\\n  draft_project_id TEXT,\\n  model_version TEXT,\\n  outcome TEXT NOT NULL CHECK (outcome IN ('unavailable', 'uncertain', 'available')),\\n  category_id TEXT,\\n  target_kind TEXT,\\n  project_id TEXT,\\n  category_probabilities_json TEXT,\\n  target_probabilities_json TEXT,\\n  accepted_category_id TEXT,\\n  accepted_target_kind TEXT,\\n  decided_at TEXT\\n);\",\"CREATE INDEX expense_suggestion_events_owner_time\\n  ON expense_suggestion_events(owner_id, created_at);\",\"-- Lazy per-account counters. No cron, daily maintenance or GET-side writes.\\n-- Capacity is cumulative: archival/deletion do not refund slots.\\nCREATE TABLE ledger_plan_usage (\\n  owner_id TEXT PRIMARY KEY,\\n  projects INTEGER NOT NULL,\\n  records INTEGER NOT NULL,\\n  month TEXT NOT NULL,\\n  writes INTEGER NOT NULL,\\n  minute INTEGER NOT NULL,\\n  minute_writes INTEGER NOT NULL,\\n  jev_reserved_microusd INTEGER NOT NULL,\\n  project_cap INTEGER NOT NULL,\\n  record_cap INTEGER NOT NULL,\\n  minute_cap INTEGER NOT NULL,\\n  month_cap INTEGER NOT NULL,\\n  jev_cap INTEGER NOT NULL,\\n  project_delta INTEGER NOT NULL,\\n  record_delta INTEGER NOT NULL,\\n  jev_delta INTEGER NOT NULL,\\n  previous_month TEXT NOT NULL,\\n  previous_minute INTEGER NOT NULL,\\n  CONSTRAINT plan_clock_fence CHECK(month>=previous_month AND minute>=previous_minute),\\n  CONSTRAINT plan_project_limit CHECK(project_delta=0 OR projects<=project_cap),\\n  CONSTRAINT plan_record_limit CHECK(record_delta=0 OR records<=record_cap),\\n  CONSTRAINT plan_write_rate CHECK(minute_writes<=minute_cap),\\n  CONSTRAINT plan_monthly_write_limit CHECK(writes<=month_cap),\\n  CONSTRAINT plan_max_required CHECK(jev_delta=0 OR jev_cap>0),\\n  CONSTRAINT plan_jev_budget_limit CHECK(jev_delta=0 OR jev_reserved_microusd<=jev_cap)\\n);\"],\"migrations\":[{\"name\":\"0001_ledger.sql\",\"sha256\":\"f3a358ff148454fcda978ab399d14b8f251363efe3de841eb0577240e92969f2\"},{\"name\":\"0002_identity_billing_keys.sql\",\"sha256\":\"450feb13aeceef853045b92a4b4d0148ee5e140fa61cb7bd0eb4d8367c70abc9\"},{\"name\":\"0003_ledger_suggestions.sql\",\"sha256\":\"8cc88d00396bff8a67127d64dcd767cf1f8aa5579853a640905ff861f8e9f728\"},{\"name\":\"0004_ledger_plan_usage.sql\",\"sha256\":\"febe80c0f21a9a3697a1a9a6b8b7f35ed1dc28fc831b65ce948e87e9df41d514\"}],\"indexes\":{\"ledger_projects\":4,\"expense_categories\":3,\"expenses\":4,\"expense_events\":2,\"expense_create_idempotency\":1,\"app_state\":1,\"d1_command_guard\":0,\"api_keys\":3,\"account_entitlement_authority\":1,\"billing_webhook_receipts\":1,\"billing_public_catalog\":0,\"expense_suggestion_budget\":1,\"expense_suggestion_events\":2,\"ledger_plan_usage\":1},\"primary\":{\"ledger_projects\":[\"id\"],\"expense_categories\":[\"id\"],\"expenses\":[\"id\"],\"expense_events\":[\"id\"],\"expense_create_idempotency\":[\"owner_id\",\"idempotency_key\"],\"app_state\":[\"name\"],\"d1_command_guard\":[],\"api_keys\":[\"id\"],\"account_entitlement_authority\":[\"owner_id\"],\"billing_webhook_receipts\":[\"event_id\"],\"billing_public_catalog\":[\"id\"],\"expense_suggestion_budget\":[\"owner_id\",\"day\"],\"expense_suggestion_events\":[\"id\"],\"ledger_plan_usage\":[\"owner_id\"]}}")
